MM.mnemo[20] = {"cards":[{"id":"ko-k3-0346","w":"울다","cs":"plakat, brečet","en":"to cry","p":"v","o":"k","ex":"울어도","exc":"i když pláčeš","m":"ㄹ odpadá před ㄴ, ㅂ, ㅅ: 우는 아이 = plačící dítě. Opak 웃다 (smát se).","tv":["울어요"]},{"id":"ko-k3-0347","w":"켜다","cs":"zapnout; rozsvítit","en":"to turn on","p":"v","o":"k","ex":"불을 켜도 사무실이 어두워요.","exc":"I když rozsvítím světlo, v kanceláři je tma. (을 → 4. pád; 이 → 1. pád)","m":"Častá spojení: 불을 켜다 (rozsvítit světlo), 컴퓨터를 켜다 (zapnout počítač). Opak: 끄다 (vypnout, zhasnout).","tv":["켜요"]},{"id":"ko-k3-0348","w":"고프다","cs":"hladový; mít hlad (배가 고프다)","en":"to be hungry (배가 고프다)","p":"a","o":"k","ex":"배가 안 고파도 먹어야 돼요.","exc":"I když nemáš hlad, musíš se najíst. (가 → 1. pád)","m":"Skoro vždy ve spojení 배가 고프다 (mít hlad, doslova ‚břicho je hladové‘). Nepravidelné časování s ㅡ → 배가 고파요.","tv":["고파요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0350","w":"세일하다","cs":"být ve slevě; mít výprodej","en":"to be on sale","p":"v","o":"e","ex":"세일해도 너무 비싸요.","exc":"I když je to ve slevě, je to moc drahé.","m":"Výpůjčka z anglického ‚sale‘ (výprodej, sleva) + 하다. Korejci říkají i 세일 중이다 = probíhá výprodej.","tv":["세일해요"]},{"id":"ko-k3-0351","w":"늦다","cs":"přijít pozdě; mít zpoždění; pozdní","en":"to be late","p":"v","o":"k","ex":"조금 늦어도 괜찮아요?","exc":"Nevadí, když přijdu trochu pozdě?","exa":"조금 늦어도 괜찮아요? ⚠","m":"Vazby: 학교에 늦다 (přijít pozdě do školy), 늦어서 죄송합니다 (omlouvám se za zpoždění). Opak: 일찍 (brzy).","tv":["늦어요"]},{"id":"ko-k3-0352","w":"오래 걸리다","cs":"trvat dlouho","en":"to take a long time","p":"f","o":"k","ex":"택시를 타도, 시간이 오래 걸려요.","exc":"I když si vezmeš taxík, zabere to spoustu času. (를 → 4. pád; 이 → 1. pád)","m":"오래 (dlouho) + 걸리다 (trvat, zabrat čas). Častá otázka: 얼마나 오래 걸려요? = Jak dlouho to trvá?"},{"id":"ko-k3-0353","w":"냄새","cs":"vůně; zápach","en":"smell","p":"n","o":"k","ex":"냄새는 이상해도 맛있어요.","exc":"I když to divně voní, je to chutné. (는 → téma)","m":"냄새가 나다 = je cítit (něco voní/páchne), 냄새를 맡다 = čichat. Hezká vůně je i 향기."},{"id":"ko-k3-0354","w":"계속","cs":"stále; pořád; nepřetržitě","en":"continuously; keep (doing)","p":"o","o":"s","ex":"경화 씨한테 계속 전화를 해도 안 받아요.","exc":"I když Kjonghwě pořád volám, nezvedá to. (한테 → komu; 를 → 4. pád)","m":"繼 navázat + 續 pokračovat = stále, nepřetržitě. Jako sloveso 계속하다 = pokračovat v něčem.","r":["gye-繼","sok-續"]},{"id":"ko-k3-0355","w":"아직도","cs":"pořád ještě; stále ještě","en":"still","p":"o","o":"k","ex":"아직도요?","exc":"Pořád ještě?","m":"아직 (ještě) + -도 (i, dokonce) = pořád ještě (často s překvapením nebo netrpělivostí). Samotné 아직 = zatím, ještě."},{"id":"ko-k3-0356","w":"사무실","cs":"kancelář","en":"office","p":"n","o":"s","ex":"불을 켜도 사무실이 어두워요.","exc":"I když rozsvítím světlo, v kanceláři je tma. (을 → 4. pád; 이 → 1. pád)","m":"事 záležitost + 務 povinnost, úkol + 室 místnost = místnost pro vyřizování pracovních úkolů, tedy kancelář.","r":["sa-事","mu-務","sil-室"]},{"id":"ko-k3-0357","w":"어둡다","cs":"tmavý","en":"to be dark (어두워요)","p":"a","o":"k","ex":"불을 켜도 사무실이 어두워요.","exc":"I když rozsvítím světlo, v kanceláři je tma. (을 → 4. pád; 이 → 1. pád)","m":"Nepravidelné časování s ㅂ → 어두워요 (je tma / tmavý). Opak: 밝다 (světlý, jasný)."},{"id":"ko-k3-0358","w":"이미","cs":"už; již","en":"already","p":"o","o":"k","ex":"지금 가도 이미 늦었어요.","exc":"I když vyrazím teď, už je pozdě.","m":"Konstatuje prostý fakt ‚už‘ (na rozdíl od 벌써, které vyjadřuje překvapení, že se něco stalo tak brzy)."},{"id":"ko-k3-0359","w":"튼튼하다","cs":"pevný; bytelný; odolný; zdravý","en":"to be sturdy, strong","p":"a","o":"k","ex":"이 차가 조금 비싸도 튼튼해요.","exc":"I když je tohle auto trochu drahé, je bytelné. (가 → 1. pád)","m":"Zdvojený kořen 튼튼 vyjadřuje pevnost a odolnost. Říká se i o zdravém těle nebo zubech: 이가 튼튼하다 = mít pevné zuby."},{"id":"ko-k3-0360","w":"사과","cs":"jablko","en":"apple","p":"n","o":"k","ex":"이 사과는 예쁘지 않아도 맛은 있어요.","exc":"I když tohle jablko není hezké, chutná dobře. (는 → téma)","m":"Stejně znějící 사과 (謝過) = omluva, 사과하다 = omluvit se. Jablko je ryze korejské slovo."},{"id":"ko-k3-0361","w":"넣다","cs":"dát dovnitř; vložit; strčit (do)","en":"to put in","p":"v","o":"k","ex":"책이 커도 이 가방에 넣을 수 있어요.","exc":"I když je ta kniha velká, dá se strčit do téhle tašky. (이 → 1. pád; 에 → kam)","m":"Vyslovuje se [너타], před samohláskou ㅎ mizí → 넣어요 [너어요]. Vazba: 가방에 넣다 = dát do tašky. Opak: 꺼내다 (vyndat)."},{"id":"ko-k3-0362","w":"핸드폰","cs":"mobil; mobilní telefon","en":"cell phone","p":"n","o":"e","ex":"책이 없어도 핸드폰으로 공부할 수 있어요.","exc":"I když nemáš učebnici, můžeš se učit přes mobil. (이 → 1. pád; 으로 → pomocí)","m":"Konglish z angl. ‚hand phone‘ (telefon do ruky) = mobil. Často se používá i sinokorejské 휴대폰."},{"id":"ko-k3-0363","w":"침대","cs":"postel","en":"bed","p":"n","o":"s","ex":"침대에 누워도 잠이 안 와요.","exc":"I když si lehnu do postele, nemůžu usnout. (에 → kam; 이 → 1. pád)","m":"寢 spát + 臺 podstavec, vyvýšené místo = podstavec na spaní, tedy postel. Vazba: 침대에 눕다 = lehnout si do postele.","r":["chim-寢","dae-臺"]},{"id":"ko-k3-0364","w":"잠이 안 오다","cs":"nemoci usnout","en":"can’t fall asleep","p":"f","o":"k","ex":"침대에 누워도 잠이 안 와요.","exc":"I když si lehnu do postele, nemůžu usnout. (에 → kam; 이 → 1. pád)","m":"Doslova ‚spánek (잠) nepřichází (안 오다)‘. Kladný tvar 잠이 오다 znamená ‚chce se mi spát / jde na mě spánek‘."}],"gram":{"id":"ko-k3-g20","w":"-아/어/여도","en":"Even if, Even though","cs":"i když…, i kdyby…, přestože…","vy":"Koncovka -아/어/여도 se tvoří stejně jako přítomný čas slovesa či přídavného jména bez koncového -요, ke kterému se přidá -도 (např. 가도, 먹어도, 공부해도). Spojuje dvě části jedné věty ve významu ‚i když…, i kdyby…, přestože…‘ a vyjadřuje, že druhá část platí bez ohledu na první. Stejný význam mezi dvěma samostatnými větami vyjadřuje spojka 그래도.","m":"Skládá se z přítomného kmene (-아/어/여) a částice -도 (také, i) — doslova ‚i když dělám X, platí Y‘. Pozor na nepravidelná slova na ㅂ, u nichž se ㅂ mění na 우: 눕다 → 누워도, 어렵다 → 어려워도.","s":[["-아/어/여도","i když, i kdyby, přestože (obdoba spojky 그래도 uvnitř jedné věty)"],["보아도 = 봐도","i když se podíváš / i kdyby ses podíval"],["울어도","i když pláčeš / i kdybys plakal"],["공부해도 (= 공부하여도)","i když se učíš / i kdyby ses učil"],["요즘에 바빠도, 운동은 하고 있어요.","I když mám v poslední době napilno, pořád cvičím."],["집에 가도, 밥이 없어요.","I když půjdu domů, není tam žádné jídlo."],["택시를 타도, 시간이 오래 걸려요.","Trvá to dlouho, i když si vezmu taxík."],["석진 씨는 제가 전화를 해도 안 받아요.","I když Sokdžinovi volám, nezvedá to."],["냄새는 이상해도 맛있어요.","I když to divně voní, je to chutné."],["바빠도 한국에 갈 거예요.","I kdybych měl napilno, do Koreje pojedu."],["경화 씨한테 계속 전화를 해도 안 받아요.","I když Kjonghwě pořád volám, nezvedá telefon."],["불을 켜도 사무실이 어두워요.","I když rozsvítím, v kanceláři je tma."],["배가 안 고파도 먹어야 돼요.","I když nemáš hlad, musíš se najíst."],["책이 커도 이 가방에 넣을 수 있어요.","I když je ta kniha velká, vejde se mi do téhle tašky."],["제 친구는 영어는 못해도 중국어는 잘해요.","I když můj kamarád neumí anglicky, čínsky mluví dobře."],["침대에 누워도 잠이 안 와요.","I když si lehnu do postele, nemůžu usnout."]]}};
